body_template.@value:
--- [Event Definition] ---------------------------
Title:       ${event_definition_title}
Description: ${event_definition_description}
Type:        ${event_definition_type}
--- [Event] --------------------------------------
Alert Replay:         ${http_external_uri}alerts/${event.id}/replay-search
Timestamp:            ${event.timestamp}
Message:              ${event.message}
Source:               ${event.source}
Key:                  ${event.key}
Priority:             ${event.priority}
Alert:                ${event.alert}
Timestamp Processing: ${event.timestamp}
Timerange Start:      ${event.timerange_start}
Timerange End:        ${event.timerange_end}
Fields:
${foreach event.fields field}  ${field.key}: ${field.value}
${end}
${if backlog}
--- [What happened] ------------------------------
${foreach backlog message}
${if message.fields.Operation}  ${message.fields.Operation}  by  ${message.fields.UserId}
${end}${if message.fields.ObjectId}      Target:        ${message.fields.ObjectId}
${end}${if message.fields.DisplayName_NewValue}      Name:          ${message.fields.DisplayName_NewValue}
${end}${if message.fields.Target_Name}      Target name:   ${message.fields.Target_Name}
${end}${if message.fields.AppId_NewValue}      App ID:        ${message.fields.AppId_NewValue}
${end}${if message.fields.Role_DisplayName_NewValue}      Role:          ${message.fields.Role_DisplayName_NewValue}
${end}${if message.fields.AppRole_Value_NewValue}      Permission:    ${message.fields.AppRole_Value_NewValue}
${end}${if message.fields.ConsentContext_IsAdminConsent_NewValue}      Admin consent: ${message.fields.ConsentContext_IsAdminConsent_NewValue}
${end}${if message.fields.Name}      Rule name:     ${message.fields.Name}
${end}${if message.fields.ForwardTo}      Forward to:    ${message.fields.ForwardTo}
${end}${if message.fields.RedirectTo}      Redirect to (rule): ${message.fields.RedirectTo}
${end}${if message.fields.ForwardAsAttachmentTo}      Forward as attach: ${message.fields.ForwardAsAttachmentTo}
${end}${if message.fields.ForwardingSmtpAddress}      Mailbox forward: ${message.fields.ForwardingSmtpAddress}
${end}${if message.fields.ForwardingAddress}      Mailbox forward 2: ${message.fields.ForwardingAddress}
${end}${if message.fields.MoveToFolder}      Move to folder: ${message.fields.MoveToFolder}
${end}${if message.fields.From}      Rule condition: ${message.fields.From}
${end}${if message.fields.CopyTo}      Copy to:       ${message.fields.CopyTo}
${end}${if message.fields.BlindCopyTo}      Bcc to:        ${message.fields.BlindCopyTo}
${end}${if message.fields.RedirectMessageTo}      Redirect to:   ${message.fields.RedirectMessageTo}
${end}${if message.fields.Identity}      Mailbox:       ${message.fields.Identity}
${end}${if message.fields.AuditBypassEnabled}      Audit bypass:  ${message.fields.AuditBypassEnabled}
${end}${if message.fields.ClientIP}      Client IP:     ${message.fields.ClientIP}
${end}${if message.fields.ClientIP_country_code}      Country:       ${message.fields.ClientIP_country_code}
${end}${if message.fields.ClientIP_city_name}      City:          ${message.fields.ClientIP_city_name}
${end}${if message.fields.SiteUrl}      Site:          ${message.fields.SiteUrl}
${end}${if message.fields.SourceFileName}      File:          ${message.fields.SourceFileName}
${end}${if message.fields.additionalDetails_User_Agent}      User agent:    ${message.fields.additionalDetails_User_Agent}
${end}${if message.fields.ResultStatus}      Result:        ${message.fields.ResultStatus}
${end}${end}
${end}
${if backlog}
--- [Backlog] ------------------------------------
Last messages accounting for this alert:
${foreach backlog message}
${message}
${end}
${end}
